namespace RonSijm.FluidHumidifier.Factories.BedrockAgentCore;

public class BrowserCustomFactory(string resourceName = null, Action<Humidifier.BedrockAgentCore.BrowserCustom> factoryAction = null) : ResourceFactory<Humidifier.BedrockAgentCore.BrowserCustom>(resourceName)
{

    internal List<InnerBrowserCustomCertificateFactory> CertificatesFactories { get; set; } = [];

    internal List<InnerBrowserCustomBrowserEnterprisePolicyFactory> EnterprisePoliciesFactories { get; set; } = [];

    internal InnerBrowserCustomRecordingConfigFactory RecordingConfigFactory { get; set; }

    internal InnerBrowserCustomBrowserNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    internal InnerBrowserCustomBrowserSigningFactory BrowserSigningFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.BrowserCustom Create()
    {
        var browserCustomResult = CreateBrowserCustom();
        factoryAction?.Invoke(browserCustomResult);

        return browserCustomResult;
    }

    private Humidifier.BedrockAgentCore.BrowserCustom CreateBrowserCustom()
    {
        var browserCustomResult = new Humidifier.BedrockAgentCore.BrowserCustom
        {
            GivenName = InputResourceName,
        };

        return browserCustomResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.BrowserCustom result)
    {
        base.CreateChildren(result);

        result.Certificates = CertificatesFactories.Any() ? CertificatesFactories.Select(x => x.Build()).ToList() : null;
        result.EnterprisePolicies = EnterprisePoliciesFactories.Any() ? EnterprisePoliciesFactories.Select(x => x.Build()).ToList() : null;
        result.RecordingConfig ??= RecordingConfigFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
        result.BrowserSigning ??= BrowserSigningFactory?.Build();
    }

} // End Of Class

